From f755e50ed573d1539206a6ff3ce0721fd2dc1456 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:32:48 +0100
Subject: [PATCH] shell: fix edit mode after deleting a panel from its settings

Deleting a panel from its open Panel Settings left edit mode shrunk as
if the dialog were open, and Manage Desktops and Panels stayed. Say that
the dialog closed, and recount screens when a panel moves or is removed.

BUG: 524360
---
 shell/shellcorona.cpp | 14 ++++++++++++--
 1 file changed, 12 insertions(+), 2 deletions(-)

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 488ce30606..6623f5bf8f 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -270,11 +270,17 @@ void ShellCorona::init()
     auto updateManageContainmentsVisiblility = [this, manageContainmentsAction]() {
         QSet<int> allScreenIds;
         for (auto *cont : containments()) {
-            allScreenIds.insert(cont->screen());
+            if (!cont->destroyed()) {
+                allScreenIds.insert(cont->screen());
+            }
         }
         manageContainmentsAction->setVisible(allScreenIds.count() > 1);
     };
-    connect(this, &ShellCorona::containmentAdded, this, updateManageContainmentsVisiblility);
+    connect(this, &ShellCorona::containmentAdded, this, [this, updateManageContainmentsVisiblility](Plasma::Containment *c) {
+        connect(c, &Plasma::Containment::screenChanged, this, updateManageContainmentsVisiblility);
+        connect(c, &Plasma::Containment::destroyedChanged, this, updateManageContainmentsVisiblility);
+        updateManageContainmentsVisiblility();
+    });
     connect(this, &ShellCorona::screenRemoved, this, updateManageContainmentsVisiblility);
     updateManageContainmentsVisiblility();

@@ -1701,11 +1707,15 @@ void ShellCorona::handleContainmentAdded(Plasma::Containment *c)
         }
         auto view = this->m_panelViews.take(c);
         if (view) {
+            const bool wasConfiguring = view->isUserConfiguring();
             view->disconnect(this);
             delete view;
             if (!m_closingDown && !m_screenReorderInProgress) {
                 Q_EMIT availableScreenRectChanged(c->screen());
             }
+            if (wasConfiguring) {
+                Q_EMIT panelBeingConfiguredChanged();
+            }
         }
         const QString snapshotPath = containmentPreviewPath(c);
         if (!snapshotPath.isEmpty()) {
-- 
